<div class="module-intro"><div><span class="eyebrow">CONTROLE DE ACESSO</span><h2>Usuários e servidores</h2><p>Cadastro funcional, contas, perfis e permissões individuais.</p></div><?php if($canManageUsers): ?><button class="btn primary" data-toggle-target="user-form">＋ Novo usuário</button><?php endif; ?></div>
<form method="get" class="filter-bar"><input name="q" value="<?= e($search) ?>" placeholder="Nome, e-mail ou matrícula"><select name="status"><option value="">Todas as situações</option><?php foreach(['Ativo','Afastado','Inativo'] as $s): ?><option <?= $statusFilter===$s?'selected':'' ?>><?= e($s) ?></option><?php endforeach; ?></select><button class="btn subtle">Buscar</button></form>
<?php if($canManageUsers): ?><form id="user-form" class="panel form-panel <?= $userEdit?'':'hidden' ?>" method="post" action="<?= e($baseUrl) ?>/usuarios/salvar" enctype="multipart/form-data"><input type="hidden" name="_csrf" value="<?= e($csrf) ?>"><input type="hidden" name="id" value="<?= (int)($userEdit['id']??0) ?>"><div class="section-heading"><div><h3><?= $userEdit?'Editar usuário':'Novo usuário' ?></h3><p>Senha em branco mantém a credencial atual ao editar.</p></div></div><div class="form-grid"><label>Nome completo *<input name="name" required maxlength="160" value="<?= e($userEdit['name']??'') ?>"></label><label>Matrícula funcional<input name="registration" maxlength="40" value="<?= e($userEdit['registration']??'') ?>"></label><label>E-mail institucional *<input type="email" name="email" required value="<?= e($userEdit['email']??'') ?>"></label><label>Telefone<input name="phone" value="<?= e($userEdit['phone']??'') ?>"></label><label>Cargo ou função<input name="position" value="<?= e($userEdit['position']??'') ?>"></label><label>Setor<input name="department" value="<?= e($userEdit['department']??'') ?>"></label><label>Perfil<select name="role_id" required><?php foreach($roles as $r): ?><option value="<?= (int)$r['id'] ?>" <?= (int)($userEdit['role_id']??0)===(int)$r['id']?'selected':'' ?>><?= e($r['name']) ?></option><?php endforeach; ?></select></label><label><?= $userEdit?'Nova senha (opcional)':'Senha inicial *' ?><input type="password" name="password" <?= $userEdit?'':'required' ?> minlength="12" autocomplete="new-password"></label><label>Foto de perfil<input type="file" name="photo" accept="image/jpeg,image/png,image/webp"></label></div><div class="form-actions"><button class="btn primary">Salvar usuário</button><a class="btn subtle" href="<?= e($baseUrl) ?>/usuarios">Cancelar</a></div></form><?php endif; ?>
<section class="panel"><div class="section-heading"><div><h3>Servidores cadastrados</h3><p><?= $total ?> registros · página <?= $page ?></p></div></div><?php if(!$users): ?><div class="table-empty">Nenhum usuário encontrado.</div><?php else: ?><div class="table-wrap"><table><thead><tr><th>Servidor</th><th>Matrícula</th><th>Perfil</th><th>Situação</th><th>Último acesso</th><th>Ações</th></tr></thead><tbody><?php foreach($users as $u): ?><tr><td><b><?= e($u['name']) ?></b><small><?= e($u['email']) ?> · <?= e($u['position']??'') ?></small></td><td><?= e($u['registration']??'—') ?></td><td><?= e($u['role_name']??'Sem perfil') ?></td><td><span class="state-pill"><?= e($u['status']) ?></span></td><td><?= $u['last_login_at']?date('d/m/Y H:i',strtotime($u['last_login_at'])):'Nunca' ?></td><td class="actions-cell"><?php if($canManageUsers): ?><a class="text-link" href="<?= e($baseUrl) ?>/usuarios?edit=<?= (int)$u['id'] ?>">Editar</a><form method="post" action="<?= e($baseUrl) ?>/usuarios/status"><input type="hidden" name="_csrf" value="<?= e($csrf) ?>"><input type="hidden" name="id" value="<?= (int)$u['id'] ?>"><input type="hidden" name="status" value="<?= $u['status']==='Ativo'?'Inativo':'Ativo' ?>"><button class="btn tiny"><?= $u['status']==='Ativo'?'Bloquear':'Ativar' ?></button></form><?php endif; ?><?php if($canUserPermissions): ?><a class="text-link" href="<?= e($baseUrl) ?>/usuarios?permissions=<?= (int)$u['id'] ?>">Permissões</a><?php endif; ?></td></tr><?php endforeach; ?></tbody></table></div><?php endif; ?><?php if($total>25): ?><div class="pagination"><?php for($p=1;$p<=ceil($total/25);$p++): ?><a class="<?= $p===$page?'active':'' ?>" href="?page=<?= $p ?>&q=<?= urlencode($search) ?>&status=<?= urlencode($statusFilter) ?>"><?= $p ?></a><?php endfor; ?></div><?php endif; ?></section>
<?php if($permissionUser&&$canUserPermissions): ?><section class="panel"><div class="section-heading"><div><h3>Permissões individuais · <?= e($permissionUser['name']) ?></h3><p>As permissões individuais são somadas às permissões do perfil.</p></div></div><form method="post" action="<?= e($baseUrl) ?>/usuarios/permissoes"><input type="hidden" name="_csrf" value="<?= e($csrf) ?>"><input type="hidden" name="user_id" value="<?= (int)$permissionUser['id'] ?>"><div class="permission-grid"><?php foreach($permissionCatalog as $p): ?><label><input type="checkbox" name="permissions[]" value="<?= e($p['permission_key']) ?>" <?= in_array($p['permission_key'],$userPermissionKeys,true)?'checked':'' ?>> <span><b><?= e($p['label']) ?></b><small><?= e($p['module']) ?></small></span></label><?php endforeach; ?></div><button class="btn primary">Salvar permissões individuais</button></form></section><?php endif; ?>